def _social_account_config_update_input_schema() -> dict[str, Any]:
    return {
        "type": "object",
        "properties": {
            "account_id": {"type": "string", "minLength": 1},
            "require_approval_before_publish": {"type": "boolean"},
            "output_language": {
                "type": "string",
                "minLength": 1,
                "maxLength": 32,
                "description": (
                    "Account-wide language tag for generated overlays, captions, and "
                    "hashtags (for example en, zh-CN, ja, pt-BR)."
                ),
            },
            "required_hashtags": {
                "type": "array",
                "items": {"type": "string"},
                "maxItems": 50,
                "description": (
                    "Account-wide required hashtags. Omit to preserve the current setting; "
                    "pass an empty array to clear it."
                ),
            },
        },
        "required": ["account_id"],
        "anyOf": [
            {"required": ["require_approval_before_publish"]},
            {"required": ["output_language"]},
            {"required": ["required_hashtags"]},
        ],
    }


def _social_account_config_batch_update_input_schema() -> dict[str, Any]:
    return {
        "type": "object",
        "properties": {
            "account_updates": {
                "type": "array",
                "minItems": 1,
                "maxItems": 200,
                "description": (
                    "Per-account publish config updates. Each object sets the fields "
                    "present for that account; an omitted field is preserved and an "
                    "empty required_hashtags array clears it."
                ),
                "items": {
                    "type": "object",
                    "properties": {
                        "account_id": {"type": "string", "minLength": 1},
                        "require_approval_before_publish": {"type": "boolean"},
                        "output_language": {
                            "type": "string",
                            "minLength": 1,
                            "maxLength": 32,
                            "description": (
                                "Account-wide language tag for generated overlays, "
                                "captions, and hashtags (for example en, zh-CN, ja, pt-BR)."
                            ),
                        },
                        "required_hashtags": {
                            "type": "array",
                            "items": {"type": "string"},
                            "maxItems": 50,
                            "description": (
                                "Account-wide required hashtags. Omit to preserve the "
                                "current setting; pass an empty array to clear it."
                            ),
                        },
                    },
                    "required": ["account_id"],
                },
            },
        },
        "required": ["account_updates"],
    }


