def _social_account_version_create_input_schema() -> dict[str, Any]:
    return {
        "type": "object",
        "properties": {
            "account_id": {"type": "string", "minLength": 1},
            "schedule_rules": {
                "type": "array",
                "items": {"type": "object"},
                "description": (
                    "Publish rules. BGM options (mutually exclusive): "
                    "(1) bgm_asset_ids + bgm_strategy ('rotate'|'random') — pick "
                    "per-occurrence from the account's attached BGM library "
                    "(TikTok CloudPhone only; attach via +assets-set "
                    "--bgm-asset-id); (2) bgm_by_platform — one fixed CloudPhone "
                    "same-style reference: the value is a REFERENCE VIDEO whose "
                    "sound is reused, not a music id. For TikTok pass a "
                    'video/photo (post) URL or {"ref_video_id": "<video '
                    'aweme_id>"}. Music links/ids are rejected — open the music '
                    "page, pick a video that uses the sound, and pass that "
                    "video's URL. Bare numeric strings are rejected too: music "
                    "ids and video ids are indistinguishable and a music id "
                    "publishes with the wrong sound."
                ),
            },
            "change_note": {"type": ["string", "null"], "maxLength": 1000},
        },
        "required": ["account_id", "schedule_rules"],
    }


